// Group the list's cards into a digest
const cards = $input.all().map(i => i.json);
const today = new Date().toISOString().slice(0,10);
const overdue = [], dueToday = [], lines = [];
for (const c of cards) {
  const due = c.due ? c.due.slice(0,10) : null;
  const link = c.shortUrl || ('https://trello.com/c/' + (c.shortLink||''));
  lines.push('\u2022 ' + c.name + (due ? ' (due ' + due + ')' : '') + ' \u2014 ' + link);
  if (due && due < today && !c.dueComplete) overdue.push(c.name);
  else if (due === today) dueToday.push(c.name);
}
return [{ json: { total: cards.length, overdue, dueToday, lines } }];

